import React, { useState, useEffect, useMemo, memo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Link } from 'react-router-dom';
import {
    ResponsiveContainer, BarChart, Bar, LineChart, Line,
    CartesianGrid, XAxis, YAxis, Tooltip, Legend
} from 'recharts';
import { FaBuilding, FaBolt, FaBus, FaLeaf, FaBullhorn, FaUsers, FaChartLine } from 'react-icons/fa';
import api from '../services/api';
import Skeleton from '../components/common/Skeleton';
import { useToast } from '../context/ToastContext';
import { useWebSocket } from '../context/WebSocketContext';
import InstitutionalAnalytics from '../components/intelligence/InstitutionalAnalytics';
import Card from '../components/common/Card';
import { useNavigate } from 'react-router-dom';

const AdminDashboard = () => {
    const navigate = useNavigate();
    const [stats, setStats] = useState(null);
    const [loading, setLoading] = useState(true);
    const { addToast } = useToast();
    const { publish } = useWebSocket();

    // Broadcast State
    const [bTitle, setBTitle] = useState('');
    const [bMessage, setBMessage] = useState('');

    useEffect(() => {
        const fetchStats = async () => {
            try {
                const response = await api.get('/dashboard/stats');
                setStats(response.data);
            } catch (error) {
                console.error("Failed to fetch admin stats. Using defaults.", error);
                setStats({
                    infrastructureUtil: 78.5, energyOptimization: 85.2, transportEfficiency: 92.0,
                    sustainabilityIndex: 88.7, totalBuildings: 12, totalClassrooms: 48,
                });
            } finally {
                setLoading(false);
            }
        };
        fetchStats();
    }, []);

    const handleBroadcast = async (e) => {
        e.preventDefault();
        try {
            await api.post(`/notifications/admin/broadcast?title=${encodeURIComponent(bTitle)}&message=${encodeURIComponent(bMessage)}&type=SYSTEM`);

            // Push real-time event via raw websockets
            publish('/app/broadcast', {
                sender: 'ADMIN',
                title: bTitle,
                message: bMessage,
                severity: 'HIGH'
            });

            addToast('Broadcast sent globally!', 'success');
            setBTitle('');
            setBMessage('');
        } catch (err) {
            addToast('Failed to send broadcast', 'error');
        }
    };

    const kpiCards = useMemo(() => [
        { title: 'Infrastructure Utilization', value: `${stats?.infrastructureUtil ?? 0}%`, icon: <FaBuilding />, color: 'green', class: 'green', link: '/simulations/classroom' },
        { title: 'Energy Optimization', value: `${stats?.energyOptimization ?? 0}`, icon: <FaBolt />, color: 'yellow', class: 'yellow', link: '/simulations/energy' },
        { title: 'Transport Efficiency', value: `${stats?.transportEfficiency ?? 0}%`, icon: <FaBus />, color: 'teal', class: 'teal', link: '/transport' },
        { title: 'Sustainability Index', value: `${stats?.sustainabilityIndex ?? 0}`, icon: <FaLeaf />, color: 'red', class: 'red', link: '/dashboard/sustainability' },
    ], [stats]);

    const chartData = useMemo(() => [
        { name: 'Mon', Energy: 4000, Transport: 2400 },
        { name: 'Tue', Energy: 3000, Transport: 1398 },
        { name: 'Wed', Energy: 2000, Transport: 9800 },
        { name: 'Thu', Energy: 2780, Transport: 3908 },
        { name: 'Fri', Energy: 1890, Transport: 4800 },
        { name: 'Sat', Energy: 2390, Transport: 3800 },
        { name: 'Sun', Energy: 3490, Transport: 4300 },
    ], []);

    if (loading) return (
        <div style={{ padding: '24px' }}>
            <Skeleton height="40px" width="300px" style={{ marginBottom: '20px' }} />
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '16px', marginBottom: '20px' }}>
                <Skeleton height="120px" /><Skeleton height="120px" /><Skeleton height="120px" /><Skeleton height="120px" />
            </div>
            <Skeleton height="400px" />
        </div>
    );

    return (
        <motion.div initial="hidden" animate="visible" variants={stagger} style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>

            {/* Header / Breadcrumb Mirror from Student */}
            {/* Dashboard header removed as per user request */}

            {/* KPI Cards Row - Using stu-kpi-row classes */}
            <div className="stu-kpi-row">
                {kpiCards.map((card, i) => (
                    <div key={i} className={`stu-kpi-card ${card.class}`} onClick={() => navigate(card.link)}>
                        <div className="kpi-main">
                            <div className="kpi-value">{card.value}</div>
                            <div className="kpi-label">{card.title}</div>
                        </div>
                        <div className="kpi-icon">{card.icon}</div>
                        <div className="kpi-more">View details →</div>
                    </div>
                ))}
            </div>

            {/* Main Content Layout */}
            <div className="admin-main-grid" style={{ display: 'grid', gridTemplateColumns: '1fr 320px', gap: '20px' }}>
                {/* Analytics Chart */}
                <div className="stu-info-card" style={{ borderTopColor: '#0B2C6B' }}>
                    <div className="info-header" style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                        <FaChartLine color="#0B2C6B" />
                        <span>Weekly Simulation Analytics</span>
                    </div>
                    <div className="info-body">
                        <div style={{ height: '300px', padding: '10px' }}>
                            <ResponsiveContainer width="100%" height="100%">
                                <LineChart data={chartData}>
                                    <CartesianGrid strokeDasharray="3 3" vertical={false} />
                                    <XAxis dataKey="name" />
                                    <YAxis />
                                    <Tooltip />
                                    <Legend />
                                    <Line type="monotone" dataKey="Energy" stroke="#0B2C6B" strokeWidth={2} dot={{ r: 4 }} />
                                    <Line type="monotone" dataKey="Transport" stroke="#f39c12" strokeWidth={2} dot={{ r: 4 }} />
                                </LineChart>
                            </ResponsiveContainer>
                        </div>
                    </div>
                </div>

                {/* Broadcast Panel */}
                <div className="stu-info-card" style={{ borderTopColor: '#3c8dbc' }}>
                    <div className="info-header" style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                        <FaBullhorn color="#3c8dbc" />
                        <span>Global Broadcast</span>
                    </div>
                    <div className="info-body">
                        <form onSubmit={handleBroadcast} style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                            <input
                                type="text"
                                placeholder="Broadcast Title"
                                value={bTitle}
                                onChange={e => setBTitle(e.target.value)}
                                required
                                style={{ padding: '10px', borderRadius: '4px', border: '1px solid #ddd', fontSize: '14px' }}
                            />
                            <textarea
                                placeholder="Type your global message here..."
                                value={bMessage}
                                onChange={e => setBMessage(e.target.value)}
                                required
                                rows="4"
                                style={{ padding: '10px', borderRadius: '4px', border: '1px solid #ddd', fontSize: '14px', resize: 'none' }}
                            />
                            <button className="table-btn primary" type="submit" style={{ width: '100%', padding: '10px', background: '#3c8dbc', borderColor: '#3c8dbc' }}>
                                Broadcast Globally
                            </button>
                        </form>
                    </div>
                </div>
            </div>

            {/* Institutional Analytics Section */}
            <div className="stu-info-card" style={{ borderTopColor: '#00a65a' }}>
                <div className="info-header">
                    Institutional Intelligence Dashboard
                </div>
                <div className="info-body">
                    <InstitutionalAnalytics />
                </div>
            </div>

        </motion.div>
    );
};

export default AdminDashboard;

import React, { useState } from 'react';
import { FaEye, FaEyeSlash } from 'react-icons/fa';
import { useToast } from '../context/ToastContext';
import api from '../services/api';

const ChangePassword = () => {
    const [newPassword, setNewPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [showPassword, setShowPassword] = useState(false);
    const { addToast } = useToast();

    const handleSave = async () => {
        if (!newPassword || !confirmPassword) {
            addToast('Please fill in both fields', 'error');
            return;
        }
        if (newPassword !== confirmPassword) {
            addToast('Passwords do not match', 'error');
            return;
        }

        try {
            // Making API request
            const response = await api.post('/auth/change-password', { newPassword });
            addToast('Password successfully changed!', 'success');
            setNewPassword('');
            setConfirmPassword('');
        } catch (error) {
            console.error("Change password error:", error);
            const errorMsg = error.response?.data?.message || 'Failed to update password. Please try again.';
            addToast(errorMsg, 'error');
        }
    };

    return (
        <div className="stu-report-page">
            <div className="stu-info-card" style={{ maxWidth: '500px', margin: '20px 0' }}>
                <div style={{ padding: '12px 15px', borderBottom: '1px solid #f4f4f4', fontSize: '14px', color: '#333' }}>
                    Change Password
                </div>
                <form autoComplete="off" style={{ padding: '20px' }}>
                    <div style={{ marginBottom: '15px' }}>
                        <label style={{ display: 'block', fontSize: '13px', fontWeight: 'bold', marginBottom: '8px' }}>
                            New Password <span style={{ color: 'red' }}>*</span>
                        </label>
                        <div style={{ position: 'relative', display: 'flex', alignItems: 'center' }}>
                            <input
                                type={showPassword ? "text" : "password"}
                                value={newPassword}
                                onChange={(e) => setNewPassword(e.target.value)}
                                autoComplete="new-password"
                                style={{ width: '100%', height: '38px', padding: '6px 40px 6px 12px', border: '1px solid #ccc', borderRadius: '4px', outline: 'none' }}
                                placeholder="Enter new password"
                            />
                            <span
                                onClick={() => setShowPassword(!showPassword)}
                                style={{ position: 'absolute', right: '12px', cursor: 'pointer', color: '#666', fontSize: '16px' }}
                            >
                                {showPassword ? <FaEyeSlash /> : <FaEye />}
                            </span>
                        </div>
                    </div>

                    <div style={{ marginBottom: '20px' }}>
                        <label style={{ display: 'block', fontSize: '13px', fontWeight: 'bold', marginBottom: '8px' }}>
                            Repeat New Password <span style={{ color: 'red' }}>*</span>
                        </label>
                        <div style={{ position: 'relative', display: 'flex', alignItems: 'center' }}>
                            <input
                                type={showPassword ? "text" : "password"}
                                value={confirmPassword}
                                onChange={(e) => setConfirmPassword(e.target.value)}
                                autoComplete="new-password"
                                style={{ width: '100%', height: '38px', padding: '6px 40px 6px 12px', border: '1px solid #ccc', borderRadius: '4px', outline: 'none' }}
                                placeholder="Repeat new password"
                            />
                            <span
                                onClick={() => setShowPassword(!showPassword)}
                                style={{ position: 'absolute', right: '12px', cursor: 'pointer', color: '#666', fontSize: '16px' }}
                            >
                                {showPassword ? <FaEyeSlash /> : <FaEye />}
                            </span>
                        </div>
                    </div>

                    <button
                        onClick={(e) => { e.preventDefault(); handleSave(); }}
                        style={{ background: '#dc3545', color: 'white', border: 'none', padding: '8px 24px', borderRadius: '4px', cursor: 'pointer', fontWeight: 'bold', transition: 'background 0.2s' }}
                        onMouseEnter={(e) => e.target.style.background = '#c82333'}
                        onMouseLeave={(e) => e.target.style.background = '#dc3545'}
                    >
                        Save
                    </button>
                </form>
            </div>

            <div style={{ marginTop: '30px', color: '#777', fontSize: '12px' }}>
                © All rights reserved.
                <span style={{ float: 'right' }}><img src="/assets/images/rit-icon.png" alt="RIT-IMS" style={{ width: '16px', height: '16px', objectFit: 'contain' }} /> RIT-IMS</span>
            </div>
        </div>
    );
};

export default ChangePassword;

import React, { useState } from 'react';
import api from '../services/api';

const CrowdPage = () => {
    const [buildingId, setBuildingId] = useState('1');
    const [occupancy, setOccupancy] = useState(500);
    const [result, setResult] = useState(null);

    const handleSimulate = async () => {
        try {
            const response = await api.post('/crowd/simulate', { buildingId, occupancy });
            setResult(JSON.parse(response.data.resultJson));
        } catch (error) {
            setResult({
                congestionLevel: 'HIGH',
                estimatedEvacuationTimeMin: 15,
                readinessScore: 70
            });
        }
    };

    return (
        <div className="space-y-6">
            <h1 className="page-header">Crowd Flow & Emergency Simulation</h1>

            <div className="card max-w-3xl">
                <h3 className="section-header">Evacuation Parameters</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
                    <div>
                        <label className="block text-gray-700 font-medium mb-1 text-sm">Building Block</label>
                        <select
                            className="input-field"
                            value={buildingId}
                            onChange={(e) => setBuildingId(e.target.value)}
                        >
                            <option value="1">Main Block</option>
                            <option value="2">Science Block</option>
                        </select>
                    </div>
                    <div>
                        <label className="block text-gray-700 font-medium mb-1 text-sm">Current Occupancy (People)</label>
                        <input
                            type="number"
                            className="input-field"
                            value={occupancy}
                            onChange={(e) => setOccupancy(e.target.value)}
                        />
                    </div>
                </div>
                <button
                    onClick={handleSimulate}
                    className="w-full bg-red-600 text-white rounded-md px-4 py-2.5 hover:bg-red-700 font-medium transition-colors"
                >
                    Run Evacuation Simulation
                </button>
            </div>

            {result && (
                <div className={`card border-l-8 ${result.congestionLevel === 'CRITICAL' ? 'border-l-red-600' : 'border-l-green-600'}`}>
                    <h3 className="section-header !mb-3">Simulation Outcome</h3>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        <div>
                            <p className="text-sm text-gray-500">Congestion Level</p>
                            <p className={`text-xl font-bold ${result.congestionLevel === 'CRITICAL' || result.congestionLevel === 'HIGH' ? 'text-red-600' : 'text-green-600'}`}>{result.congestionLevel}</p>
                        </div>
                        <div>
                            <p className="text-sm text-gray-500">Est. Evacuation Time</p>
                            <p className="text-xl font-bold text-navy-900">{result.estimatedEvacuationTimeMin} minutes</p>
                        </div>
                        <div>
                            <p className="text-sm text-gray-500">Readiness Score</p>
                            <p className="text-xl font-bold text-navy-900">{result.readinessScore}/100</p>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default CrowdPage;

import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import {
    FiGrid,
    FiZap,
    FiTruck,
    FiUsers,
    FiBarChart2,
    FiActivity,
} from 'react-icons/fi';
import './DashboardHome.css';
import Card from '../../components/common/Card';
import AIInsightPanel from '../../components/intelligence/AIInsightPanel';

const DashboardHome = () => {
    const { user } = useAuth();
    const navigate = useNavigate();

    const stats = [
        { label: 'Total Classrooms', value: '156', trend: '+12%', trendDir: 'up', variant: 'primary', icon: <FiGrid />, link: '/dashboard/classroom' },
        { label: 'Energy Saved (kWh)', value: '8,420', trend: '+23%', trendDir: 'up', variant: 'success', icon: <FiZap />, link: '/dashboard/energy' },
        { label: 'Active Routes', value: '12', trend: 'Live', trendDir: 'up', variant: 'info', icon: <FiTruck />, link: '/dashboard/transport' },
        { label: 'Campus Population', value: '5,000', trend: 'Live', trendDir: 'up', variant: 'accent', icon: <FiUsers />, link: '/dashboard/crowd' },
        { label: 'Sustainability', value: 'A+', trend: 'Excellent', trendDir: 'up', variant: 'success', icon: <FiBarChart2 />, link: '/dashboard/sustainability' },
        { label: 'Forecast Accuracy', value: '97%', trend: 'R²=0.99', trendDir: 'up', variant: 'warning', icon: <FiActivity />, link: '/dashboard/predictive' },
    ];

    const modules = [
        {
            title: 'Smart Classroom Allocation',
            description: 'Room scheduling, occupancy monitoring, and resource optimization across campus buildings.',
            icon: <FiGrid />,
            path: '/dashboard/classroom',
            status: 'active',
        },
        {
            title: 'Energy Consumption Analytics',
            description: 'Energy monitoring, consumption simulation, and efficiency forecasting for sustainability.',
            icon: <FiZap />,
            path: '/dashboard/energy',
            status: 'active',
        },
        {
            title: 'Transport Route Optimization',
            description: 'Campus bus route planning, fleet analysis, and schedule optimization.',
            icon: <FiTruck />,
            path: '/dashboard/transport',
            status: 'active',
        },
        {
            title: 'Crowd Flow & Emergency',
            description: 'Crowd density mapping, emergency evacuation simulation, and readiness scoring.',
            icon: <FiUsers />,
            path: '/dashboard/crowd',
            status: 'active',
        },
        {
            title: 'Sustainability Dashboard',
            description: 'Environmental impact tracking, carbon footprint analysis, and SDG progress.',
            icon: <FiBarChart2 />,
            path: '/dashboard/sustainability',
            status: 'active',
        },
        {
            title: 'Predictive Analytics',
            description: 'Regression-based forecasting for enrollment, infrastructure demand, and planning.',
            icon: <FiActivity />,
            path: '/dashboard/predictive',
            status: 'active',
        },
    ];

    return (
        <div className="dashboard-home">

            <div className="stats-grid" style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(240px, 1fr))', gap: '20px', marginBottom: '32px' }}>
                {stats.map((stat, i) => (
                    <Card
                        key={i}
                        onClick={() => navigate(stat.link)}
                        hoverEffect={true}
                        style={{ padding: '24px', borderLeft: `4px solid var(--color - primary - navy)` }}
                    >
                        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '16px' }}>
                            <div style={{ fontSize: '1.5rem', color: 'var(--color-primary-navy)' }}>{stat.icon}</div>
                            <span style={{ fontSize: '0.8rem', fontWeight: 'bold', color: '#10B981' }}>{stat.trend}</span>
                        </div>
                        <div style={{ fontSize: '2rem', fontWeight: 'bold', marginBottom: '4px' }}>{stat.value}</div>
                        <div style={{ fontSize: '0.9rem', color: 'var(--theme-text-muted)', textTransform: 'uppercase', letterSpacing: '1px' }}>{stat.label}</div>
                    </Card>
                ))}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-10">
                <div className="lg:col-span-2">
                    {/* Modules */}
                    <div className="section-header">
                        <h3>Core Modules</h3>
                    </div>
                    <div className="module-grid">
                        {modules.map((mod, i) => (
                            <Link to={mod.path} className="module-card" key={i}>
                                <div className="module-card-header">
                                    <div className="module-card-icon">{mod.icon}</div>
                                    <h3>{mod.title}</h3>
                                    <span className={`module - status ${mod.status} `}>
                                        {mod.status === 'active' ? 'Active' : 'Coming Soon'}
                                    </span>
                                </div>
                                <p>{mod.description}</p>
                            </Link>
                        ))}
                    </div>
                </div>
                <div className="mt-8">
                    <AIInsightPanel />
                </div>
            </div>
        </div>
    );
};

export default DashboardHome;

import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';
import { useAuth } from '../context/AuthContext';
import Skeleton from '../components/common/Skeleton';
import { FaChalkboardTeacher, FaCalendarCheck, FaTasks, FaBook, FaUserClock, FaExclamationTriangle } from 'react-icons/fa';
import ClassRiskHeatmap from '../components/intelligence/ClassRiskHeatmap';

const FacultyDashboard = () => {
    const { user } = useAuth();
    const navigate = useNavigate();
    const [subjects, setSubjects] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchFacultyData = async () => {
            try {
                const subRes = await api.get('/academic/faculty/subjects');
                setSubjects(subRes.data);
            } catch (err) {
                console.error(err);
            } finally {
                setLoading(false);
            }
        };
        fetchFacultyData();
    }, []);

    if (loading) return (
        <div style={{ padding: '24px' }}>
            <Skeleton height="200px" />
        </div>
    );

    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
            {/* Header / Breadcrumb Mirror from Student */}
            {/* Dashboard header removed as per user request */}

            {/* KPI Cards Placeholder - Matching Student Style */}
            <div className="stu-kpi-row">
                <div className="stu-kpi-card green" onClick={() => navigate('/faculty/academics')}>
                    <div className="kpi-main">
                        <div className="kpi-value">{subjects.length}</div>
                        <div className="kpi-label">Courses</div>
                    </div>
                    <FaBook className="kpi-icon" />
                    <div className="kpi-more">More info →</div>
                </div>
                <div className="stu-kpi-card teal" onClick={() => navigate('/faculty/leaves')}>
                    <div className="kpi-main">
                        <div className="kpi-value">4</div>
                        <div className="kpi-label">Pending Requests</div>
                    </div>
                    <FaCalendarCheck className="kpi-icon" />
                    <div className="kpi-more">More info →</div>
                </div>
                <div className="stu-kpi-card yellow" onClick={() => navigate('/faculty/attendance')}>
                    <div className="kpi-main">
                        <div className="kpi-value">92%</div>
                        <div className="kpi-label">Avg Attendance</div>
                    </div>
                    <FaUserClock className="kpi-icon" />
                    <div className="kpi-more">More info →</div>
                </div>
                <div className="stu-kpi-card red" onClick={() => navigate('/faculty/analytics')}>
                    <div className="kpi-main">
                        <div className="kpi-value">2</div>
                        <div className="kpi-label">At Risk Students</div>
                    </div>
                    <FaExclamationTriangle className="kpi-icon" />
                    <div className="kpi-more">More info →</div>
                </div>
            </div>

            {/* Info Cards Row */}
            <div className="stu-info-row">
                <div className="stu-info-card">
                    <div className="info-header" style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                        <FaChalkboardTeacher color="#0B2C6B" />
                        <span>My Assigned Subjects</span>
                    </div>
                    <div className="info-body">
                        <table className="stu-data-table">
                            <thead>
                                <tr>
                                    <th>Subject Code</th>
                                    <th>Subject Name</th>
                                    <th>Status</th>
                                </tr>
                            </thead>
                            <tbody>
                                {subjects.length > 0 ? subjects.map(s => (
                                    <tr key={s.subjectId}>
                                        <td>{s.subjectCode}</td>
                                        <td>{s.subjectName}</td>
                                        <td><span className="percent-cell good">Active</span></td>
                                    </tr>
                                )) : (
                                    <tr>
                                        <td colSpan="3" style={{ textAlign: 'center', color: '#999' }}>No subjects assigned.</td>
                                    </tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>

                <div className="stu-info-card" style={{ borderTopColor: '#f39c12' }}>
                    <div className="info-header" style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                        <FaTasks color="#f39c12" />
                        <span>Recent Tasks / Approvals</span>
                    </div>
                    <div className="info-body">
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                            <div style={{ padding: '8px', borderLeft: '3px solid #f39c12', background: '#fffef0', fontSize: '13px' }}>
                                <strong>3 New Leave requests</strong> pending review for CSE-A
                            </div>
                            <div style={{ padding: '8px', borderLeft: '3px solid #00c0ef', background: '#f0fbff', fontSize: '13px' }}>
