import React, { useEffect, useState } from 'react';
import api from '../services/api';
import { Radar, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, ResponsiveContainer } from 'recharts';
import { FaLeaf, FaGlobeAmericas, FaRecycle, FaWater, FaBolt } from 'react-icons/fa';

const SustainabilityPage = () => {
    const [metrics, setMetrics] = useState(null);

    useEffect(() => {
        const fetchMetrics = async () => {
            try {
                const response = await api.get('/sustainability/history');
                const latest = response.data[response.data.length - 1];
                setMetrics(latest || {
                    energyScore: 85,
                    transportScore: 70,
                    wasteManagementScore: 90,
                    compositeIndex: 81.6,
                    carbonFootprintEstimate: 1050,
                    sdgAlignment: "SDG 7, 11, 13"
                });
            } catch (error) {
                setMetrics({
                    energyScore: 85,
                    transportScore: 70,
                    wasteManagementScore: 90,
                    compositeIndex: 81.6
                });
            }
        };
        fetchMetrics();
    }, []);

    if (!metrics) return <div className="p-10 text-center">Loading ESG Metrics...</div>;

    const radarData = [
        { subject: 'Energy', A: metrics.energyScore, fullMark: 100 },
        { subject: 'Transport', A: metrics.transportScore, fullMark: 100 },
        { subject: 'Waste', A: metrics.wasteManagementScore, fullMark: 100 },
        { subject: 'Water', A: 80, fullMark: 100 },
        { subject: 'Green Cover', A: 65, fullMark: 100 },
        { subject: 'Carbon', A: 75, fullMark: 100 },
    ];

    const categoryStats = [
        { category: 'Waste Management', score: metrics.wasteManagementScore, trend: '+5%', status: 'Excellent' },
        { category: 'Energy Efficiency', score: metrics.energyScore, trend: '+2%', status: 'Good' },
        { category: 'Water Conservation', score: 80, trend: '-1%', status: 'Stable' },
        { category: 'Carbon Footprint', score: 75, trend: '+8%', status: 'Improving' },
    ];

    return (
        <div className="space-y-6">
            <h1 className="page-header">Sustainability & ESG Detailed Report</h1>

            {/* Score Summary */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="card flex flex-col items-center justify-center p-6 border-t-4 border-teal-500">
                    <p className="text-gray-500 text-sm font-bold uppercase mb-2">Composite Index</p>
                    <div className="w-32 h-32 flex items-center justify-center rounded-full border-8 border-teal-500 text-3xl font-bold text-teal-900 bg-teal-50">
                        {metrics.compositeIndex}
                    </div>
                    <p className="mt-4 text-teal-700 font-bold uppercase tracking-wider text-sm">Rating: A+</p>
                </div>

                <div className="card lg:col-span-2">
                    <h3 className="section-header">Metric Breakdown (ESG Radar)</h3>
                    <div className="h-64">
                        <ResponsiveContainer width="100%" height="100%">
                            <RadarChart cx="50%" cy="50%" outerRadius="80%" data={radarData}>
                                <PolarGrid stroke="#E5E7EB" />
                                <PolarAngleAxis dataKey="subject" tick={{ fill: '#374151', fontSize: 11 }} />
                                <PolarRadiusAxis angle={30} domain={[0, 100]} />
                                <Radar name="Campus" dataKey="A" stroke="#0D9488" fill="#0D9488" fillOpacity={0.4} />
                            </RadarChart>
                        </ResponsiveContainer>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="card bg-teal-50 border-teal-100">
                    <h3 className="section-header text-teal-800">Carbon Footprint Analysis</h3>
                    <div className="flex items-center gap-6">
                        <div className="p-4 bg-white rounded-2xl shadow-sm">
                            <FaGlobeAmericas className="text-4xl text-teal-600" />
                        </div>
                        <div>
                            <p className="text-gray-500 text-xs font-bold uppercase">Estimated CO₂ Offset Required</p>
                            <h2 className="text-3xl font-black text-teal-900">{metrics.carbonFootprintEstimate?.toFixed(1)} <span className="text-sm font-normal text-gray-500">kg CO₂ / month</span></h2>
                        </div>
                    </div>
                    <div className="mt-4 p-3 bg-white/50 rounded-xl text-xs text-teal-700 italic font-medium">
                        "Your current energy optimization saves approximately 240kg of CO₂ per month compared to national averages."
                    </div>
                </div>

                <div className="card bg-blue-50 border-blue-100">
                    <h3 className="section-header text-blue-800">UN SDG Alignment</h3>
                    <div className="flex flex-wrap gap-2">
                        {metrics.sdgAlignment?.split(',').map(sdg => (
                            <span key={sdg} className="px-3 py-1 bg-white border border-blue-200 text-blue-700 rounded-full text-xs font-black shadow-sm">
                                {sdg.trim()}
                            </span>
                        ))}
                    </div>
                    <p className="mt-4 text-[10px] text-blue-600 font-bold leading-relaxed">
                        Rajalakshmi Institute of Technology contributes significantly to SDG 13 (Climate Action) and SDG 7 (Clean Energy) through optimized resource allocation.
                    </p>
                </div>
            </div>

            {/* Category Details Table */}
            <div className="card">
                <h3 className="section-header">Pillar-wise Sustainability Status</h3>
                <div className="overflow-x-auto">
                    <table className="min-w-full">
                        <thead className="bg-gray-50">
                            <tr>
                                <th className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase">Sustainability Pillar</th>
                                <th className="px-6 py-3 text-center text-xs font-bold text-gray-500 uppercase">Score (0-100)</th>
                                <th className="px-6 py-3 text-center text-xs font-bold text-gray-500 uppercase">MoM Trend</th>
                                <th className="px-6 py-3 text-center text-xs font-bold text-gray-500 uppercase">Status</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {categoryStats.map((item, idx) => (
                                <tr key={idx} className="hover:bg-gray-50">
                                    <td className="px-6 py-4 flex items-center gap-3">
                                        {item.category.includes('Waste') && <FaRecycle className="text-green-600" />}
                                        {item.category.includes('Energy') && <FaBolt className="text-yellow-600" />}
                                        {item.category.includes('Water') && <FaWater className="text-blue-600" />}
                                        {item.category.includes('Carbon') && <FaGlobeAmericas className="text-teal-600" />}
                                        <span className="text-sm font-semibold text-gray-700">{item.category}</span>
                                    </td>
                                    <td className="px-6 py-4 text-center">
                                        <div className="w-full bg-gray-200 rounded-full h-2.5 max-w-[100px] mx-auto">
                                            <div className="bg-teal-600 h-2.5 rounded-full" style={{ width: `${item.score}%` }}></div>
                                        </div>
                                        <span className="text-xs font-bold mt-1 inline-block">{item.score}</span>
                                    </td>
                                    <td className="px-6 py-4 text-center text-sm">
                                        <span className={item.trend.startsWith('+') ? 'text-green-600 font-bold' : 'text-red-600 font-bold'}>
                                            {item.trend}
                                        </span>
                                    </td>
                                    <td className="px-6 py-4 text-center">
                                        <span className="px-2 py-1 bg-teal-100 text-teal-800 rounded text-xs font-bold">
                                            {item.status}
                                        </span>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

export default SustainabilityPage;

import React, { useContext } from 'react';
import { ThemeContext } from '../context/ThemeContext';

const ThemeSettingsPage = () => {
    const { themePreference, setThemeMode, isDarkMode } = useContext(ThemeContext);

    const options = [
        { value: 'light', label: 'Light Mode', desc: 'Always use a bright, clean appearance.', icon: '☀️' },
        { value: 'dark', label: 'Dark Mode', desc: 'Reduce eye strain with a darker interface.', icon: '🌙' },
        { value: 'system', label: 'System Default', desc: 'Follow your device\'s current theme setting.', icon: '🖥️' },
    ];

    return (
        <div style={{ maxWidth: '600px', margin: '0 auto', padding: '30px 20px' }}>
            <h2 style={{ marginBottom: '8px', color: isDarkMode ? '#f8fafc' : '#0B2C6B' }}>Theme Settings</h2>
            <p style={{ color: isDarkMode ? '#94a3b8' : '#64748b', marginBottom: '28px', fontSize: '14px' }}>
                Choose your preferred appearance. The <strong>System Default</strong> option automatically adapts
                to your device's light or dark mode setting.
            </p>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                {options.map(opt => (
                    <button
                        key={opt.value}
                        onClick={() => setThemeMode(opt.value)}
                        style={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: '16px',
                            padding: '18px 20px',
                            borderRadius: '12px',
                            border: themePreference === opt.value
                                ? '2px solid #0B2C6B'
                                : `1px solid ${isDarkMode ? '#334155' : '#e2e8f0'}`,
                            background: themePreference === opt.value
                                ? (isDarkMode ? 'rgba(11,44,107,0.2)' : 'rgba(11,44,107,0.05)')
                                : (isDarkMode ? '#1e293b' : '#fff'),
                            cursor: 'pointer',
                            textAlign: 'left',
                            transition: 'all 0.2s ease',
                        }}
                    >
                        <span style={{ fontSize: '28px' }}>{opt.icon}</span>
                        <div>
                            <div style={{
                                fontWeight: 'bold',
                                fontSize: '15px',
                                color: isDarkMode ? '#f8fafc' : '#1e293b',
                                marginBottom: '3px'
                            }}>
                                {opt.label}
                                {themePreference === opt.value && (
                                    <span style={{
                                        marginLeft: '8px',
                                        fontSize: '11px',
                                        color: '#0B2C6B',
                                        background: 'rgba(11,44,107,0.1)',
                                        padding: '2px 8px',
                                        borderRadius: '10px',
                                        fontWeight: 'bold'
                                    }}>ACTIVE</span>
                                )}
                            </div>
                            <div style={{
                                fontSize: '13px',
                                color: isDarkMode ? '#94a3b8' : '#64748b',
                            }}>
                                {opt.desc}
                            </div>
                        </div>
                    </button>
                ))}
            </div>
        </div>
    );
};

export default ThemeSettingsPage;

import React, { useState, useEffect } from 'react';
import api from '../services/api';
import { FaBus, FaRoute, FaCheckCircle, FaSearch, FaPhoneAlt, FaMapMarkerAlt, FaClock } from 'react-icons/fa';

const TransportPage = () => {
    const [routes, setRoutes] = useState([]);
    const [searchQuery, setSearchQuery] = useState('');
    const [selectedRoute, setSelectedRoute] = useState(null);
    const [stops, setStops] = useState([]);
    const [loading, setLoading] = useState(false);
    const [searching, setSearching] = useState(false);

    useEffect(() => {
        fetchRoutes();
    }, []);

    const fetchRoutes = async () => {
        setLoading(true);
        try {
            const response = await api.get('/transport/routes');
            setRoutes(response.data);
        } catch (error) {
            console.error("Error fetching routes:", error);
        } finally {
            setLoading(false);
        }
    };

    const handleSearch = async (e) => {
        e.preventDefault();
        if (!searchQuery.trim()) {
            fetchRoutes();
            return;
        }
        setSearching(true);
        try {
            const response = await api.get(`/transport/search?query=${searchQuery}`);
            setRoutes(response.data);
        } catch (error) {
            console.error("Error searching routes:", error);
        } finally {
            setSearching(false);
        }
    };

    const viewRouteDetails = async (route) => {
        setSelectedRoute(route);
        try {
            const response = await api.get(`/transport/routes/${route.id}/stops`);
            setStops(response.data);
        } catch (error) {
            console.error("Error fetching stops:", error);
            setStops([]);
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <h1 className="page-header !mb-0">Official RIT Transport Directory</h1>
                <div className="flex flex-col sm:flex-row gap-3">
                    <div className="flex items-center gap-2 bg-blue-50 text-blue-700 px-4 py-2 rounded-lg border border-blue-100 shadow-sm font-semibold">
                        <FaPhoneAlt className="animate-pulse" />
                        <div>
                            <span className="text-xs uppercase tracking-wider block opacity-70">Helpline</span>
                            <span>63807 51700 / 75488 62447</span>
                        </div>
                    </div>
                    <div className="flex gap-2 text-sm text-gray-600 bg-gray-50 px-4 py-2 rounded-lg border border-gray-200 shadow-sm font-semibold h-full items-center">
                        <FaBus className="text-navy-900" /> {routes.length} Active Routes
                    </div>
                </div>
            </div>

            {/* Search Bar */}
            <div className="card bg-navy-900 border-none shadow-xl overflow-hidden relative">
                <div className="absolute top-0 right-0 w-64 h-64 bg-white/5 rounded-full -mr-32 -mt-32 blur-3xl"></div>
                <div className="relative z-10 p-6">
                    <h3 className="text-white text-lg font-bold mb-4 flex items-center gap-2">
                        <FaSearch className="text-gold-500" /> Find Your Route
                    </h3>
                    <form onSubmit={handleSearch} className="flex gap-3">
                        <input
                            type="text"
                            className="flex-1 bg-white/10 border border-white/20 text-white placeholder-white/50 rounded-lg px-4 py-3 focus:outline-none focus:ring-2 focus:ring-gold-500/50 transition-all font-medium"
                            placeholder="Search by Route No (e.g. R01) or Area (e.g. Ennore)..."
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                        />
                        <button
                            type="submit"
                            disabled={searching}
                            className="bg-gold-500 hover:bg-gold-600 text-navy-900 px-8 py-3 rounded-lg font-bold transition-all shadow-lg active:scale-95 disabled:opacity-50"
                        >
                            {searching ? 'Searching...' : 'Search'}
                        </button>
                    </form>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Route List */}
                <div className="lg:col-span-1 space-y-4 max-h-[70vh] overflow-y-auto pr-2 custom-scrollbar">
                    {loading ? (
                        <div className="text-center py-10 text-gray-500 font-medium">Loading Routes...</div>
                    ) : routes.length === 0 ? (
                        <div className="text-center py-10 text-gray-500 font-medium">No routes found matching your query.</div>
                    ) : (
                        routes.map((route) => (
                            <div
                                key={route.id}
                                onClick={() => viewRouteDetails(route)}
                                className={`card cursor-pointer transition-all border-l-4 hover:shadow-md ${selectedRoute?.id === route.id ? 'border-navy-900 bg-blue-50/50 scale-[1.02]' : 'border-gold-500 bg-white'}`}
                            >
                                <div className="flex justify-between items-start">
                                    <div>
                                        <div className="text-navy-900 font-black text-xl italic">{route.routeNumber}</div>
                                        <div className="text-gray-700 font-bold mt-1 line-clamp-1">{route.routeName}</div>
                                    </div>
                                    <div className="text-xs font-bold text-navy-900/60 uppercase tracking-widest">{route.busNumber}</div>
                                </div>
                                <div className="mt-3 flex items-center gap-2 text-xs text-gray-500">
                                    <FaMapMarkerAlt className="text-navy-900/40" />
                                    <span>{route.startPoint} <span className="mx-1">→</span> {route.endPoint}</span>
                                </div>
                            </div>
                        ))
                    )}
                </div>

                {/* Route Details / Timings */}
                <div className="lg:col-span-2">
                    {selectedRoute ? (
                        <div className="space-y-6 animate-in slide-in-from-right duration-500">
                            <div className="card border-t-8 border-navy-900">
                                <div className="flex justify-between items-end border-b border-gray-100 pb-4 mb-4">
                                    <div>
                                        <h2 className="text-2xl font-black text-navy-900 italic tracking-tighter">{selectedRoute.routeNumber} Detailed Schedule</h2>
                                        <p className="text-gray-600 font-medium">{selectedRoute.routeName}</p>
                                    </div>
                                    <div className="text-right">
                                        <div className="text-xs font-bold text-gray-400 uppercase">Capacity</div>
                                        <div className="text-lg font-bold text-navy-900">{selectedRoute.currentOccupancy} / {selectedRoute.capacity}</div>
                                    </div>
                                </div>

                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 bg-gray-50 p-4 rounded-xl border border-gray-100 mb-6">
                                    <div className="flex items-center gap-3">
                                        <div className="p-3 bg-white rounded-lg text-navy-900 shadow-sm"><FaPhoneAlt /></div>
                                        <div>
                                            <div className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Coordinator</div>
                                            <div className="text-sm font-bold text-navy-900">{selectedRoute.coordinatorName || 'To be Assigned'}</div>
                                            <div className="text-sm text-blue-600 font-medium">{selectedRoute.coordinatorPhone || '--'}</div>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-3">
                                        <div className="p-3 bg-white rounded-lg text-navy-900 shadow-sm"><FaBus /></div>
                                        <div>
                                            <div className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Bus Details</div>
                                            <div className="text-sm font-bold text-navy-900">{selectedRoute.busNumber}</div>
                                            <div className="text-[10px] text-gray-500 font-medium italic">Compliant with University Standards</div>
                                        </div>
                                    </div>
                                </div>

                                <h3 className="section-header !text-[16px] mb-4 flex items-center gap-2">
                                    <FaClock className="text-navy-900" /> Boarding Points & Timings
                                </h3>

                                <div className="relative pl-8 border-l-2 border-navy-900/10 space-y-6 ml-2 pt-2">
                                    {stops.length > 0 ? stops.map((stop, idx) => (
                                        <div key={stop.id} className="relative group">
                                            <div className="absolute -left-[41px] top-1/2 -translate-y-1/2 w-4 h-4 rounded-full bg-white border-4 border-navy-900 z-10 group-hover:scale-125 transition-all"></div>
                                            <div className="flex justify-between items-center p-3 rounded-lg hover:bg-gray-50 transition-all border border-transparent hover:border-gray-100">
                                                <div>
                                                    <div className="font-bold text-navy-900">{stop.stopName}</div>
                                                    {stop.landmark && <div className="text-[10px] text-gray-500 font-medium italic">{stop.landmark}</div>}
                                                </div>
                                                <div className="bg-navy-900 text-white px-3 py-1 rounded text-sm font-black italic tracking-widest">
                                                    {stop.pickupTime ? stop.pickupTime.substring(0, 5) : '--:--'} AM
                                                </div>
                                            </div>
                                        </div>
                                    )) : (
                                        <div className="text-gray-400 font-medium italic py-4">No specific boarding points recorded for this route yet.</div>
                                    )}

                                    {/* Final Stop */}
                                    <div className="relative group pt-4 border-t border-gray-100 border-dashed">
                                        <div className="absolute -left-[41px] top-[18px] w-6 h-6 rounded-full bg-navy-900 flex items-center justify-center text-white z-10">
                                            <FaCheckCircle className="text-[10px]" />
                                        </div>
                                        <div className="flex justify-between items-center">
                                            <div className="font-black text-navy-900 tracking-tight uppercase">RIT Campus</div>
                                            <div className="text-navy-900 font-bold border-b-2 border-navy-900">Reach On-Time</div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div className="h-full flex flex-col items-center justify-center card border-dashed border-2 border-gray-200 opacity-60">
                            <div className="p-6 bg-gray-50 rounded-full mb-4 text-gray-300 text-4xl">
                                <FaRoute />
                            </div>
                            <h3 className="text-gray-500 font-bold text-lg">Select a route to view its timetable</h3>
                            <p className="text-gray-400 text-sm">Click any route from the left panel to see its boarding points.</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default TransportPage;

import React, { useEffect, useState } from 'react';
import api from '../../services/api';
import { motion } from 'framer-motion';
import { FaShieldAlt, FaFire, FaUsers, FaExclamationCircle, FaChartLine } from 'react-icons/fa';
import Card from '../../components/common/Card';

const EmergencyDashboard = () => {
    const [riskScores, setRiskScores] = useState([]);
    const [loading, setLoading] = useState(true);
    const [simulationResult, setSimulationResult] = useState(null);

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        try {
            const response = await api.get('/campus/safety/risk-scores');
            setRiskScores(response.data);
            setLoading(false);
        } catch (error) {
            console.error("Risk score fetch failed", error);
        }
    };

    const runSimulation = async (buildingId, type) => {
        try {
            const response = await api.post(`/campus/safety/simulate-emergency?buildingId=${buildingId}&type=${type}`);
            setSimulationResult(response.data);
        } catch (error) {
            console.error("Simulation failed", error);
        }
    };

    return (
        <div className="space-y-6">
            <h1 className="page-header flex items-center gap-3">
                <FaShieldAlt className="text-red-600" />
                Emergency Simulation & Risk Analytics
            </h1>

            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                <Card title="Evacuation Index" value="9.2/10" icon={<FaChartLine />} trend="+0.4" trendType="up" />
                <Card title="Risk Buildings" value={riskScores.filter(r => r.aggregatedRiskScore > 7).length} icon={<FaExclamationCircle />} color="red" />
                <Card title="Active Simulations" value="2" icon={<FaFire />} color="orange" />
                <Card title="Avg Response" value="4.2m" icon={<FaUsers />} color="teal" />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                <div className="card">
                    <h3 className="section-header">Building-wise Risk Ranking</h3>
                    <div className="space-y-4">
                        {riskScores.map((score, idx) => (
                            <div key={idx} className="p-4 border border-gray-100 rounded-xl hover:shadow-md transition-shadow cursor-pointer"
                                onClick={() => runSimulation(score.building.buildingId, 'FIRE')}>
                                <div className="flex justify-between items-center">
                                    <div>
                                        <h4 className="font-bold text-gray-800">{score.building.buildingName}</h4>
                                        <div className="flex gap-4 mt-1 text-xs text-gray-500">
                                            <span>Structure: {(score.structuralRisk * 10).toFixed(1)}</span>
                                            <span>Occupancy: {(score.occupancyRisk * 10).toFixed(1)}</span>
                                        </div>
                                    </div>
                                    <div className={`w-12 h-12 rounded-full flex items-center justify-center font-bold text-lg ${score.aggregatedRiskScore > 7 ? 'bg-red-100 text-red-600' : 'bg-green-100 text-green-600'
                                        }`}>
                                        {score.aggregatedRiskScore.toFixed(1)}
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                <div className="card bg-slate-900 text-white border-none">
                    <h3 className="section-header text-white flex items-center gap-2">
                        <FaFire className="text-orange-500" />
                        Live Simulation Engine
                    </h3>
                    {simulationResult ? (
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-6">
                            <div className="grid grid-cols-2 gap-4">
                                <div className="p-4 bg-white/10 rounded-xl">
                                    <p className="text-gray-400 text-xs uppercase font-bold">Scenario</p>
                                    <p className="text-lg font-bold">{simulationResult.scenarioName}</p>
                                </div>
                                <div className="p-4 bg-white/10 rounded-xl">
                                    <p className="text-gray-400 text-xs uppercase font-bold">Risk Level</p>
                                    <p className="text-lg font-bold text-orange-400">{simulationResult.severity}</p>
                                </div>
                            </div>
                            <div className="p-6 bg-red-500/20 border border-red-500/50 rounded-2xl text-center">
                                <p className="text-sm font-bold uppercase tracking-widest text-red-400">Est. Evacuation Time</p>
                                <h2 className="text-5xl font-black mt-2">{simulationResult.estimatedEvacuationTimeMinutes.toFixed(1)}m</h2>
                                <p className="text-xs mt-3 text-red-300 italic">"Congestion likely at Block B main stairs"</p>
                            </div>
                            <button onClick={() => setSimulationResult(null)} className="w-full py-3 bg-white/10 hover:bg-white/20 transition-colors rounded-xl font-bold">
                                Clear Simulation
                            </button>
                        </motion.div>
                    ) : (
                        <div className="h-64 flex flex-col items-center justify-center text-center p-10">
                            <div className="w-16 h-16 bg-white/5 rounded-full flex items-center justify-center mb-4">
                                <FaShieldAlt className="text-gray-400 text-2xl" />
                            </div>
                            <p className="text-gray-400 font-medium">Select a building to trigger a safety simulation</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default EmergencyDashboard;

import React, { useEffect, useState } from 'react';
import api from '../../services/api';
import { FaTools, FaMicroscope, FaExclamationTriangle, FaCheckCircle, FaHistory } from 'react-icons/fa';
import Card from '../../components/common/Card';

const MaintenanceModule = () => {
    const [assets, setAssets] = useState([]);
    const [criticalAssets, setCriticalAssets] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchData = async () => {
            try {
                const criticalRes = await api.get('/campus/assets/critical');
                setCriticalAssets(criticalRes.data);
                // Defaulting to first department (CSE=1) for demo
                const assetsRes = await api.get('/campus/assets/dept/1');
                setAssets(assetsRes.data);
                setLoading(false);
            } catch (error) {
                console.error("Asset fetch failed", error);
            }
        };
        fetchData();
    }, []);

    const recordMaintenance = async (assetId) => {
        try {
            await api.post(`/campus/assets/${assetId}/maintenance?description=Scheduled Preventive&cost=500.0&type=PREVENTIVE`);
            // Refresh
            const criticalRes = await api.get('/campus/assets/critical');
            setCriticalAssets(criticalRes.data);
        } catch (error) {
            console.error("Maintenance logging failed", error);
        }
    };

    return (
        <div className="space-y-6">
            <h1 className="page-header flex items-center gap-3">
                <FaTools className="text-teal-600" />
                Maintenance & Asset Monitoring
            </h1>

            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                <Card title="Total Assets" value={assets.length} icon={<FaMicroscope />} />
                <Card title="Critical Repairs" value={criticalAssets.length} color="red" icon={<FaExclamationTriangle />} />
                <Card title="Health Score" value="94%" color="green" icon={<FaCheckCircle />} />
                <Card title="Upcoming Maint." value="12" color="teal" icon={<FaHistory />} />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <div className="lg:col-span-2 card">
                    <h3 className="section-header">Lab Equipment Status</h3>
                    <div className="overflow-x-auto">
                        <table className="min-w-full">
                            <thead className="bg-gray-50 text-xs text-gray-500 font-bold uppercase">
                                <tr>
                                    <th className="px-6 py-3 text-left">Asset</th>
                                    <th className="px-6 py-3 text-center">Status</th>
                                    <th className="px-6 py-3 text-center">Next Maintenance</th>
                                    <th className="px-6 py-3 text-center">Action</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {assets.map((asset, idx) => (
                                    <tr key={idx} className="hover:bg-gray-50 text-sm">
                                        <td className="px-6 py-4">
                                            <div className="font-bold text-gray-800">{asset.assetName}</div>
                                            <div className="text-[10px] text-gray-500">SN: {asset.serialNumber}</div>
                                        </td>
                                        <td className="px-6 py-4 text-center">
                                            <span className={`px-2 py-0.5 rounded-full text-[10px] font-black uppercase ${asset.status === 'OPERATIONAL' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'
                                                }`}>
                                                {asset.status}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4 text-center text-gray-600">
                                            {asset.nextMaintenanceDate || 'Not Scheduled'}
                                        </td>
                                        <td className="px-6 py-4 text-center">
                                            <button onClick={() => recordMaintenance(asset.id)} className="p-2 hover:bg-teal-50 text-teal-600 rounded-lg">
                                                <FaTools />
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>

                <div className="card bg-red-50/50 border-red-100">
                    <h3 className="section-header text-red-900 border-red-200">Critical Alerts</h3>
                    <div className="space-y-3">
                        {criticalAssets.map((asset, idx) => (
                            <div key={idx} className="p-3 bg-white border border-red-200 rounded-xl shadow-sm">
                                <p className="font-bold text-red-900 text-xs">{asset.assetName}</p>
                                <p className="text-[10px] text-red-700 mt-1">Status: {asset.status}</p>
                                <button onClick={() => recordMaintenance(asset.id)} className="mt-2 w-full py-1.5 bg-red-600 text-white text-[10px] font-black uppercase rounded-lg hover:bg-red-700">
                                    Schedule Repair
                                </button>
                            </div>
                        ))}
                        {criticalAssets.length === 0 && (
                            <div className="text-center py-10">
                                <FaCheckCircle className="text-green-500 mx-auto text-3xl mb-2" />
                                <p className="text-xs text-gray-500 font-bold">All assets healthy</p>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default MaintenanceModule;

import React, { useState, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import * as XLSX from 'xlsx';
import { FaCloudUploadAlt, FaFileExcel, FaCheckCircle, FaExclamationTriangle, FaTrash } from 'react-icons/fa';
import api from '../../services/api';

const UploadMarks = () => {
    const [file, setFile] = useState(null);
    const [marksData, setMarksData] = useState([]);
    const [error, setError] = useState('');
    const [isDragging, setIsDragging] = useState(false);
    const [uploading, setUploading] = useState(false);
    const [success, setSuccess] = useState(false);

    // For manual entry or overriding defaults
    const [subjectCode, setSubjectCode] = useState('');
    const [uploadMode, setUploadMode] = useState('ALL');

    const fileInputRef = useRef(null);

    const handleDragOver = (e) => {
        e.preventDefault();
        setIsDragging(true);
    };

    const handleDragLeave = (e) => {
        e.preventDefault();
        setIsDragging(false);
    };

    const handleDrop = (e) => {
        e.preventDefault();
        setIsDragging(false);
        const droppedFile = e.dataTransfer.files[0];
        if (droppedFile) {
            processFile(droppedFile);
        }
    };

    const handleFileChange = (e) => {
        const selectedFile = e.target.files[0];
        if (selectedFile) {
            processFile(selectedFile);
        }
    };

    const processFile = (file) => {
        setError('');
        setSuccess(false);
        const fileExt = file.name.split('.').pop().toLowerCase();

        if (!['xlsx', 'xls', 'csv'].includes(fileExt)) {
            setError('Please upload a valid Excel or CSV file.');
            return;
        }

        setFile(file);

        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const data = new Uint8Array(e.target.result);
                const workbook = XLSX.read(data, { type: 'array' });
                const sheetName = workbook.SheetNames[0];
                const worksheet = workbook.Sheets[sheetName];

                // Convert to JSON
                const jsonData = XLSX.utils.sheet_to_json(worksheet, { defval: '' });

                if (jsonData.length === 0) {
                    setError('The uploaded file is empty.');
                    return;
                }

                // Client-side validation to ensure required columns exist
                const firstRow = jsonData[0];
                // Check for RegNo or StudentData
                const hasStudentId = firstRow.hasOwnProperty('StudentData') || firstRow.hasOwnProperty('RegNo') || firstRow.hasOwnProperty('Email');
                if (!hasStudentId) {
                    setError('Missing required column: "StudentData", "RegNo", or "Email"');
                    return;
                }

                setMarksData(jsonData);
            } catch (err) {
                console.error("Excel Parsing Error:", err);
                setError('Failed to parse the file. Ensure it is a valid spreadsheet.');
            }
        };
        reader.readAsArrayBuffer(file);
    };

    const clearFile = () => {
        setFile(null);
        setMarksData([]);
        setError('');
        setSuccess(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
    };

    const handleUpload = async () => {
        if (!marksData || marksData.length === 0) {
            setError("No data to upload.");
            return;
        }

        if (!subjectCode && !marksData[0].hasOwnProperty('SubjectCode')) {
            setError("Please provide a Subject Code either in the spreadsheet or the input field above.");
            return;
        }

        setUploading(true);
        setError('');

        // Normalize payload to conform to expected backend constraints
        const parseOptionalFloat = (val) => {
            if (val === undefined || val === null || val === '') return null;
            const parsed = parseFloat(val);
            return isNaN(parsed) ? null : parsed;
        };

        const payload = marksData.map(row => {
            const base = {
                studentIdentifier: row.StudentData || row.RegNo || row.Email,
                subjectCode: row.SubjectCode || subjectCode,
                semesterGrade: row.SemesterGrade || null
            };

            if (uploadMode === 'ALL' || uploadMode === 'CAT') {
                base.cat1 = parseOptionalFloat(row.CAT1);
                base.cat2 = parseOptionalFloat(row.CAT2);
                base.cat3 = parseOptionalFloat(row.CAT3);
            }
            if (uploadMode === 'ALL' || uploadMode === 'ASSIGNMENT') {
                base.assignment = parseOptionalFloat(row.Assignment);
            }

            return base;
        });

        try {
            // Send bulk upload dataset to backend
            await api.post('/marks/bulk-upload', payload);
            setSuccess(true);
            setMarksData([]);
            setFile(null);
            setSubjectCode('');
        } catch (err) {
            console.error("Upload error:", err);
            setError(err.response?.data?.message || 'Failed to sync marks. Please try again.');
        } finally {
            setUploading(false);
        }
    };

    return (
        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} style={{ padding: '24px', maxWidth: '900px', margin: '0 auto' }}>
            <div style={{ marginBottom: '32px' }}>
                <h1 style={{ fontSize: '2rem', color: 'var(--text-primary)', fontWeight: '700', marginBottom: '8px' }}>Batch Marks Processing</h1>
                <p style={{ color: 'var(--text-secondary)' }}>Upload a spreadsheet (.xlsx, .csv) to securely auto-sync combined marks, CAT grades, or Assignments directly into the academic database.</p>
            </div>

            {error && (
                <div style={{ padding: '16px', background: 'rgba(239, 68, 68, 0.1)', borderLeft: '4px solid #EF4444', color: '#EF4444', borderRadius: '8px', marginBottom: '24px', display: 'flex', alignItems: 'center', gap: '12px' }}>
                    <FaExclamationTriangle /> <span>{error}</span>
                </div>
            )}

            {success && (
                <div style={{ padding: '16px', background: 'rgba(16, 185, 129, 0.1)', borderLeft: '4px solid #10B981', color: '#10B981', borderRadius: '8px', marginBottom: '24px', display: 'flex', alignItems: 'center', gap: '12px' }}>
                    <FaCheckCircle /> <span>Successfully pushed {success} marks to the core academic database! CGPA triggers fired.</span>
                </div>
            )}

            <div style={{ display: 'grid', gridTemplateColumns: marksData.length > 0 ? '1fr 2fr' : '1fr', gap: '24px' }}>
                {/* Upload Zone */}
                <div style={{ background: 'var(--bg-card)', padding: '24px', borderRadius: '16px', border: '1px solid var(--border-color)', boxShadow: 'var(--shadow-soft)' }}>
                    <div style={{ display: 'flex', gap: '16px', marginBottom: '16px' }}>
                        <div style={{ flex: 1 }}>
                            <label style={{ display: 'block', marginBottom: '8px', fontWeight: '600', color: 'var(--text-primary)' }}>Fallback Subject Code</label>
                            <input
                                type="text"
                                placeholder="e.g. CS3401 (If missing in Excel)"
                                value={subjectCode}
                                onChange={(e) => setSubjectCode(e.target.value)}
                                style={{ width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid var(--border-color)', background: 'var(--bg-light)', color: 'var(--text-primary)' }}
                            />
                        </div>
                        <div style={{ flex: 1 }}>
                            <label style={{ display: 'block', marginBottom: '8px', fontWeight: '600', color: 'var(--text-primary)' }}>Upload Target Mode</label>
                            <select
                                value={uploadMode}
                                onChange={(e) => setUploadMode(e.target.value)}
                                style={{ width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid var(--border-color)', background: 'var(--bg-light)', color: 'var(--text-primary)' }}
                            >
                                <option value="ALL">Combined Marks (All Columns)</option>
                                <option value="CAT">CAT Exams Only</option>
                                <option value="ASSIGNMENT">Assignments Only</option>
                            </select>
                        </div>
                    </div>

                    <div
                        onDragOver={handleDragOver}
                        onDragLeave={handleDragLeave}
                        onDrop={handleDrop}
                        style={{
                            border: `2px dashed ${isDragging ? '#007bff' : 'var(--border-color)'}`,
                            backgroundColor: isDragging ? 'rgba(0, 123, 255, 0.05)' : 'var(--bg-light)',
                            borderRadius: '16px',
                            padding: '40px 20px',
                            textAlign: 'center',
                            cursor: 'pointer',
                            transition: 'all 0.3s ease'
                        }}
                        onClick={() => fileInputRef.current?.click()}
                    >
                        <input
                            type="file"
                            ref={fileInputRef}
                            onChange={handleFileChange}
                            accept=".xlsx, .xls, .csv"
                            style={{ display: 'none' }}
                        />
                        <FaCloudUploadAlt style={{ fontSize: '3rem', color: isDragging ? '#007bff' : '#9ca3af', marginBottom: '16px' }} />
                        <h3 style={{ fontSize: '1.2rem', color: 'var(--text-primary)', marginBottom: '8px' }}>
                            {file ? file.name : 'Drag & Drop Excel File'}
                        </h3>
                        <p style={{ color: 'var(--text-secondary)', fontSize: '0.9rem' }}>
                            {file ? `${(file.size / 1024).toFixed(2)} KB` : 'or click to browse from device'}
                        </p>
                    </div>

                    {file && (
                        <div style={{ marginTop: '24px', display: 'flex', gap: '12px' }}>
                            <button
                                onClick={handleUpload}
                                disabled={uploading}
                                style={{ flex: 1, padding: '12px', borderRadius: '8px', background: 'var(--color-primary-navy)', color: 'white', fontWeight: 'bold', border: 'none', cursor: uploading ? 'not-allowed' : 'pointer', opacity: uploading ? 0.7 : 1 }}
                            >
                                {uploading ? 'Processing & Syncing...' : 'Upload & Compute'}
                            </button>
                            <button
                                onClick={clearFile}
                                disabled={uploading}
                                style={{ padding: '12px 16px', borderRadius: '8px', background: '#EF4444', color: 'white', border: 'none', cursor: 'pointer', display: 'flex', alignItems: 'center' }}
                            >
                                <FaTrash />
                            </button>
                        </div>
                    )}
                </div>

                {/* Data Preview Zone */}
                {marksData.length > 0 && (
                    <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} style={{ background: 'var(--bg-card)', padding: '24px', borderRadius: '16px', border: '1px solid var(--border-color)', boxShadow: 'var(--shadow-soft)', overflow: 'hidden', display: 'flex', flexDirection: 'column' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
                            <h3 style={{ fontSize: '1.2rem', fontWeight: '600', display: 'flex', alignItems: 'center', gap: '8px' }}>
                                <FaFileExcel color="#10B981" /> Data Extracted Preview
                            </h3>
                            <span style={{ padding: '4px 12px', background: 'var(--bg-light)', borderRadius: '20px', fontSize: '0.875rem', fontWeight: '600' }}>
                                {marksData.length} records
                            </span>
                        </div>

                        <div style={{ overflowX: 'auto', flex: 1, border: '1px solid var(--border-color)', borderRadius: '8px' }}>
                            <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', fontSize: '0.9rem' }}>
                                <thead>
                                    <tr style={{ background: 'var(--bg-light)', color: 'var(--text-secondary)' }}>
                                        <th style={{ padding: '12px', borderBottom: '1px solid var(--border-color)' }}>Student / RegNo</th>
                                        <th style={{ padding: '12px', borderBottom: '1px solid var(--border-color)' }}>CAT-1</th>
                                        <th style={{ padding: '12px', borderBottom: '1px solid var(--border-color)' }}>CAT-2</th>
                                        <th style={{ padding: '12px', borderBottom: '1px solid var(--border-color)' }}>CAT-3</th>
                                        <th style={{ padding: '12px', borderBottom: '1px solid var(--border-color)' }}>Assign</th>
                                        <th style={{ padding: '12px', borderBottom: '1px solid var(--border-color)' }}>Sem. Grade</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {marksData.slice(0, 5).map((row, idx) => (
                                        <tr key={idx}>
                                            <td style={{ padding: '12px', borderBottom: '1px solid var(--border-color)', fontWeight: '500' }}>{row.StudentData || row.RegNo || row.Email || 'MISSING'}</td>
                                            <td style={{ padding: '12px', borderBottom: '1px solid var(--border-color)' }}>{row.CAT1 || '-'}</td>
                                            <td style={{ padding: '12px', borderBottom: '1px solid var(--border-color)' }}>{row.CAT2 || '-'}</td>
                                            <td style={{ padding: '12px', borderBottom: '1px solid var(--border-color)' }}>{row.CAT3 || '-'}</td>
                                            <td style={{ padding: '12px', borderBottom: '1px solid var(--border-color)' }}>{row.Assignment || '-'}</td>
                                            <td style={{ padding: '12px', borderBottom: '1px solid var(--border-color)' }}>{row.SemesterGrade || '-'}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                            {marksData.length > 5 && (
                                <div style={{ padding: '12px', textAlign: 'center', background: 'var(--bg-light)', fontSize: '0.85rem', color: 'var(--text-secondary)' }}>
                                    + {marksData.length - 5} more rows detected...
                                </div>
                            )}
                        </div>
                    </motion.div>
                )}
            </div>
        </motion.div>
    );
};

export default UploadMarks;

import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { workflowApi } from '../../services/enterpriseApi';
import { useAuth } from '../../context/AuthContext';
import { useToast } from '../../context/ToastContext';

const Certificates = () => {
    const { user } = useAuth();
    const [requests, setRequests] = useState([]);
    const [search, setSearch] = useState('');
    const [type, setType] = useState('BONAFIDE');
    const [submitting, setSubmitting] = useState(false);
    const { addToast } = useToast();

    useEffect(() => {
        const fetchReqs = async () => {
            try {
                const studentId = user?.id || 1;
                const res = await workflowApi.getCertificates(studentId);
                setRequests(res.data || []);
            } catch (err) { }
        };
        fetchReqs();
    }, [user]);

    const handleApply = async () => {
        setSubmitting(true);
        try {
            const studentId = user?.id || 1;
            const res = await workflowApi.requestCertificate(studentId, type);
            setRequests([...requests, res.data]);
            addToast('Certificate request submitted successfully!', 'success');
        } catch (err) {
            console.error(err);
            addToast('Failed to submit certificate request. Please try again.', 'error');
        } finally {
            setSubmitting(false);
        }
    };

    return (
        <div className="stu-report-page" style={{ padding: '24px' }}>
            <div className="cert-apply-row" style={{ display: 'flex', gap: '16px', alignItems: 'center', marginBottom: '24px', background: 'var(--bg-card)', padding: '24px', borderRadius: '12px', border: '1px solid var(--border-color)', boxShadow: '0 4px 15px rgba(0,0,0,0.05)' }}>
                <div style={{ flex: 1 }}>
                    <label style={{ display: 'block', marginBottom: '8px', fontSize: '0.9rem', color: 'var(--text-secondary)' }}>Certificate Type</label>
                    <select value={type} onChange={(e) => setType(e.target.value)} style={{ width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid var(--border-color)' }}>
                        <option value="BONAFIDE">Bonafide Certificate</option>
                        <option value="FEE_RECEIPT">Fee Receipt</option>
                        <option value="TRANSCRIPT">Transcript</option>
                    </select>
                </div>
                <button
                    onClick={handleApply}
                    disabled={submitting}
                    style={{ alignSelf: 'flex-end', background: '#00a65a', color: 'white', border: 'none', padding: '12px 24px', borderRadius: '8px', fontWeight: 'bold', cursor: submitting ? 'wait' : 'pointer', boxShadow: '0 4px 12px rgba(0,166,90,0.3)' }}
                >
                    {submitting ? 'Applying...' : 'Apply Certificate'}
                </button>
            </div>

            <div className="stu-info-card" style={{ padding: '20px' }}>
                <div className="info-header" style={{ border: 'none', fontSize: '1.2rem', color: '#333', marginBottom: '16px' }}>
                    My Certificate Applications
                </div>

                <div style={{ overflowX: 'auto' }}>
                    <table className="stu-data-table" style={{ width: '100%' }}>
                        <thead>
                            <tr style={{ background: 'var(--bg-light)' }}>
                                <th style={{ textAlign: 'left', padding: '12px' }}>Date Requested</th>
                                <th style={{ textAlign: 'left', padding: '12px' }}>Certificate Type</th>
                                <th style={{ textAlign: 'center', padding: '12px' }}>Status</th>
                                <th style={{ textAlign: 'right', padding: '12px' }}>Action</th>
                            </tr>
                        </thead>
                        <tbody>
                            {requests.length === 0 ? (
                                <tr>
                                    <td colSpan="4" style={{ textAlign: 'center', padding: '30px', color: '#777', background: '#f9f9f9', borderBottom: '1px solid var(--border-color)' }}>
                                        No certificate requests found.
                                    </td>
                                </tr>
                            ) : (
                                requests.map(req => (
                                    <tr key={req.id} style={{ borderBottom: '1px solid var(--border-color)' }}>
                                        <td style={{ padding: '12px' }}>{new Date(req.createdAt).toLocaleDateString()}</td>
                                        <td style={{ padding: '12px', fontWeight: '500' }}>{req.certificateType}</td>
                                        <td style={{ textAlign: 'center', padding: '12px' }}>
                                            <span style={{
                                                padding: '4px 8px', borderRadius: '4px', fontSize: '0.85rem', fontWeight: 'bold',
                                                background: req.status === 'APPROVED' ? '#DEF7EC' : req.status === 'REJECTED' ? '#FDE8E8' : '#FEF3C7',
                                                color: req.status === 'APPROVED' ? '#03543F' : req.status === 'REJECTED' ? '#9B1C1C' : '#92400E'
                                            }}>
                                                {req.status}
                                            </span>
                                        </td>
                                        <td style={{ textAlign: 'right', padding: '12px' }}>
                                            {req.status === 'APPROVED' && req.pdfUrl ? (
                                                <a href={req.pdfUrl} target="_blank" rel="noreferrer" style={{ color: 'var(--color-primary-navy)', fontWeight: 'bold', textDecoration: 'none' }}>Download PDF</a>
                                            ) : (
                                                <span style={{ color: 'var(--text-secondary)' }}>-</span>
                                            )}
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

export default Certificates;

import React, { useState, useEffect } from 'react';
import api from '../../services/api';

const LeaveOD = () => {
