    const sectionBodyStyle = {
        overflow: 'hidden',
        background: cardBg,
        border: `1px solid ${borderColor}`,
        marginTop: '-11px',
        marginBottom: '10px',
        padding: '20px',
        borderRadius: '0 0 8px 8px',
        transition: 'background 0.3s, border-color 0.3s'
