                            <InfoRow label="Late Entry" value="..." />
                            <InfoRow label="Course" value="..." />
                            <InfoRow label="Batch" value="..." />
                            <InfoRow label="Academic Year" value="..." />
                            <InfoRow label="Semester" value="..." />
