export default Profile;

import React, { useState, useEffect } from 'react';
import { FaBookOpen, FaCheckCircle, FaTimesCircle } from 'react-icons/fa';
import { motion } from 'framer-motion';
import { workflowApi } from '../../services/enterpriseApi';
import { useAuth } from '../../context/AuthContext';

const SubjectRegistration = () => {
    const { user } = useAuth();
    const [registrations, setRegistrations] = useState([]);
    const [loading, setLoading] = useState(true);
    const [message, setMessage] = useState(null);

    // Mock subjects for the UI showcase
    const availableElectives = [
        { id: 101, name: 'Advanced Machine Learning', code: 'CS701', capacity: 60, enrolled: 58 },
        { id: 102, name: 'Cloud Native Computing', code: 'CS702', capacity: 60, enrolled: 60 },
        { id: 103, name: 'Quantum Cryptography', code: 'CS703', capacity: 40, enrolled: 12 },
    ];

    useEffect(() => {
        const fetchRegs = async () => {
            try {
                // Fake student ID of 1 for structural wiring
                const studentId = user?.id || 1;
                const res = await workflowApi.getRegistrations(studentId);
                setRegistrations(res.data || []);
            } catch (err) {
                console.error(err);
                setRegistrations([]);
            } finally {
                setLoading(false);
            }
        };
        fetchRegs();
    }, [user]);

    const handleRegister = async (subjectId) => {
        try {
            const studentId = user?.id || 1;
            const res = await workflowApi.registerSubject(studentId, subjectId);
            setRegistrations([...registrations, res.data]);
            setMessage({ type: 'success', text: 'Successfully registered for subject!' });
        } catch (err) {
            setMessage({ type: 'error', text: 'Registration failed. Subject may be full or already registered.' });
        }
    };

    const isRegistered = (subId) => registrations.some(r => r.subject?.id === subId);

    return (
        <div className="stu-page" style={{ padding: '24px' }}>
            <div className="stu-page-header" style={{ marginBottom: '24px' }}>
                <h2>Elective Subject Registration Portal</h2>
                <p>Register for open electives. Real-time capacity enforced.</p>
            </div>

            {message && (
                <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} style={{ padding: '16px', background: message.type === 'success' ? '#DEF7EC' : '#FDE8E8', color: message.type === 'success' ? '#03543F' : '#9B1C1C', borderRadius: '8px', marginBottom: '24px', display: 'flex', alignItems: 'center', gap: '12px' }}>
                    {message.type === 'success' ? <FaCheckCircle /> : <FaTimesCircle />} {message.text}
                </motion.div>
            )}

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '20px' }}>
                {availableElectives.map(subject => {
                    const isFull = subject.enrolled >= subject.capacity;
                    const registered = isRegistered(subject.id);
                    const percentFull = (subject.enrolled / subject.capacity) * 100;

                    return (
                        <motion.div key={subject.id} whileHover={{ y: -4 }} style={{ background: 'var(--bg-card)', padding: '24px', borderRadius: '12px', border: '1px solid var(--border-color)', boxShadow: '0 4px 15px rgba(0,0,0,0.05)', display: 'flex', flexDirection: 'column' }}>
                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '16px' }}>
                                <div>
                                    <h3 style={{ margin: 0, fontSize: '1.1rem', color: 'var(--text-primary)' }}>{subject.name}</h3>
                                    <div style={{ color: 'var(--text-secondary)', fontSize: '0.9rem', marginTop: '4px' }}>{subject.code}</div>
                                </div>
                                <FaBookOpen style={{ color: 'var(--color-primary-navy)', fontSize: '1.5rem', opacity: 0.2 }} />
                            </div>

                            <div style={{ marginBottom: '20px', flex: 1 }}>
                                <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.85rem', marginBottom: '8px', color: 'var(--text-secondary)' }}>
                                    <span>Capacity</span>
                                    <span style={{ fontWeight: 'bold', color: isFull ? '#EF4444' : 'var(--text-primary)' }}>{subject.enrolled} / {subject.capacity}</span>
                                </div>
                                <div style={{ height: '8px', background: 'var(--bg-light)', borderRadius: '4px', overflow: 'hidden' }}>
                                    <motion.div
                                        initial={{ width: 0 }}
                                        animate={{ width: `${percentFull}%` }}
                                        transition={{ duration: 1, ease: 'easeOut' }}
                                        style={{ height: '100%', background: isFull ? '#EF4444' : percentFull > 80 ? '#F59E0B' : '#10B981' }}
                                    />
                                </div>
                            </div>

                            <button
                                disabled={isFull || registered || loading}
                                onClick={() => handleRegister(subject.id)}
                                style={{
                                    padding: '12px', width: '100%', borderRadius: '8px', border: 'none', fontWeight: 'bold', cursor: (isFull || registered) ? 'not-allowed' : 'pointer',
                                    background: registered ? '#DEF7EC' : isFull ? '#F1F5F9' : 'var(--color-primary-navy)',
                                    color: registered ? '#03543F' : isFull ? '#94A3B8' : 'white'
                                }}
                            >
                                {registered ? 'Registered ✓' : isFull ? 'Capacity Full' : 'Register Now'}
                            </button>
                        </motion.div>
                    );
                })}
            </div>
        </div>
    );
};

export default SubjectRegistration;

import React, { useState, useEffect } from 'react';
import api from '../../services/api';
import Skeleton from '../../components/common/Skeleton';

const ALIGN_TIMES = ['09:00:00', '10:00:00', '11:00:00', '13:00:00', '14:00:00', '15:00:00'];
const DAYS = ['MONDAY', 'TUESDAY', 'WEDNESDAY', 'THURSDAY', 'FRIDAY'];

const Timetable = () => {
    const [timetable, setTimetable] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchTimetable = async () => {
            try {
                // Adjust to the existing student timetable endpoint if available
                const res = await api.get('/academic/student/timetable').catch(() => ({ data: [] }));
                setTimetable(res.data || []);
            } catch (err) {
                console.error(err);
            } finally {
                setLoading(false);
            }
        };
        fetchTimetable();
    }, []);

    const getSlot = (day, timePrefix) => {
        return timetable.find(t => t.dayOfWeek === day && t.startTime.startsWith(timePrefix));
    };

    if (loading) return <div style={{ padding: '24px' }}><Skeleton height="400px" /></div>;

    return (
        <div style={{ padding: '24px', maxWidth: '1200px', margin: '0 auto' }}>
            <h2 style={{ marginBottom: '24px', color: '#0B2C6B' }}>My Weekly Time Table</h2>

            <div style={{ overflowX: 'auto', borderRadius: '12px', boxShadow: '0 2px 10px rgba(0,0,0,0.05)', WebkitOverflowScrolling: 'touch' }}>
                <table className="stu-data-table" style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'center', minWidth: '700px' }}>
                    <thead style={{ background: '#0B2C6B', color: 'white' }}>
                        <tr>
                            <th style={{ padding: '16px', borderRight: '1px solid rgba(255,255,255,0.2)' }}>Day / Time</th>
                            {ALIGN_TIMES.map(t => (
                                <th key={t} style={{ padding: '16px', borderRight: '1px solid rgba(255,255,255,0.2)' }}>
                                    {t.substring(0, 5)} - {parseInt(t.substring(0, 2)) + 1}:00
                                </th>
                            ))}
                        </tr>
                    </thead>
                    <tbody>
                        {DAYS.map((day, rowIndex) => (
                            <tr key={day} style={{ borderBottom: '1px solid var(--border-color, #e2e8f0)' }}>
                                <td style={{ padding: '16px', fontWeight: 'bold', borderRight: '1px solid #e2e8f0', color: '#333' }}>
                                    {day}
                                </td>
                                {ALIGN_TIMES.map(time => {
                                    const slot = getSlot(day, time.substring(0, 5));
                                    return (
                                        <td key={time} style={{ padding: '12px', borderRight: '1px solid var(--border-color, #e2e8f0)', height: '70px', verticalAlign: 'middle' }}>
                                            {slot ? (
                                                <div style={{ background: '#e0f2fe', padding: '8px', borderRadius: '8px', color: '#0369a1', fontSize: '0.85rem' }}>
                                                    <div style={{ fontWeight: 'bold' }}>{slot.subject?.subjectName || slot.subject?.subjectCode || 'Class'}</div>
                                                    <div>{slot.faculty?.user?.firstName}</div>
                                                    <div style={{ fontSize: '0.7rem', color: '#64748b', marginTop: '4px' }}>Section: {slot.section}</div>
                                                </div>
                                            ) : (
                                                <span style={{ color: '#cbd5e1' }}>--</span>
                                            )}
                                        </td>
                                    );
                                })}
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default Timetable;

import React, { useState, useEffect } from 'react';
import { GoogleMap, useJsApiLoader, Marker, DirectionsRenderer } from '@react-google-maps/api';
import api from '../../services/api';
import { FaBus, FaMapMarkerAlt, FaClock } from 'react-icons/fa';

const containerStyle = {
    width: '100%',
    height: '500px',
    borderRadius: '12px'
};

const center = {
    lat: 13.0827, // Chennai coordinates as default for RIT
    lng: 80.2707
};

const TransportRoute = ({ studentId }) => {
    const { isLoaded } = useJsApiLoader({
        id: 'google-map-script',
        googleMapsApiKey: "YOUR_GOOGLE_MAPS_API_KEY" // Placeholder for user to fill
    });

    const [routeData, setRouteData] = useState(null);
    const [directions, setDirections] = useState(null);

    useEffect(() => {
        const fetchRoute = async () => {
            try {
                const res = await api.get(`/api/operations/transport/student/${studentId}`);
                if (res.data && res.data.length > 0) {
                    setRouteData(res.data[0].route);
                }
            } catch (err) {
                console.error("Failed to fetch transport data", err);
            }
        };
        fetchRoute();
    }, [studentId]);

    useEffect(() => {
        if (isLoaded && routeData) {
            const directionsService = new window.google.maps.DirectionsService();
            directionsService.route(
                {
                    origin: routeData.startLocation,
                    destination: routeData.endLocation,
                    travelMode: window.google.maps.TravelMode.DRIVING
                },
                (result, status) => {
                    if (status === window.google.maps.DirectionsStatus.OK) {
                        setDirections(result);
                    } else {
                        console.error(`error fetching directions ${result}`);
                    }
                }
            );
        }
    }, [isLoaded, routeData]);

    if (!isLoaded) return <div>Loading Maps...</div>;

    return (
        <div style={{ padding: '24px', display: 'flex', flexDirection: 'column', gap: '20px' }}>
            <div style={{ background: 'white', padding: '24px', borderRadius: '16px', boxShadow: '0 4px 12px rgba(0,0,0,0.05)' }}>
                <h2 style={{ margin: '0 0 16px 0', borderBottom: '2px solid #0B2C6B', paddingBottom: '10px' }}>
                    <FaBus /> My Transport Route
                </h2>

                {routeData ? (
                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 2fr', gap: '24px' }}>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
                            <div style={{ background: '#f8fafc', padding: '16px', borderRadius: '10px' }}>
                                <div style={{ color: '#64748b', fontSize: '0.85rem' }}>Route Name</div>
                                <div style={{ fontWeight: 'bold' }}>{routeData.routeName}</div>
                            </div>
                            <div style={{ background: '#f8fafc', padding: '16px', borderRadius: '10px' }}>
                                <div style={{ color: '#64748b', fontSize: '0.85rem' }}>Vehicle Number</div>
                                <div style={{ fontWeight: 'bold' }}>{routeData.vehicleNumber}</div>
                            </div>
                            <div style={{ background: '#f8fafc', padding: '16px', borderRadius: '10px' }}>
                                <div style={{ color: '#64748b', fontSize: '0.85rem' }}>Pickup Point</div>
                                <div style={{ fontWeight: 'bold' }}><FaMapMarkerAlt color="#EF4444" /> {routeData.startLocation}</div>
                            </div>
                            <div style={{ background: '#f8fafc', padding: '16px', borderRadius: '10px' }}>
                                <div style={{ color: '#64748b', fontSize: '0.85rem' }}>Estimated Time</div>
                                <div style={{ fontWeight: 'bold' }}><FaClock color="#0B2C6B" /> 07:30 AM</div>
                            </div>
                        </div>

                        <GoogleMap
                            mapContainerStyle={containerStyle}
                            center={center}
                            zoom={12}
                        >
                            {directions && <DirectionsRenderer directions={directions} />}
                        </GoogleMap>
                    </div>
                ) : (
                    <p>No transport route assigned yet.</p>
                )}
            </div>
        </div>
    );
};

export default TransportRoute;
